package com.sgasubtitler.ui;
import com.sgasubtitler.engine.*;import com.sgasubtitler.model.*;import javax.swing.*;import java.awt.*;import java.awt.image.*;import java.util.*;import java.util.List;
public final class PreviewPanel extends JPanel {private SgaFile file;private List<Subtitle>subtitles=List.of();private SubtitleStyle style=SubtitleStyle.defaults();private int frame;private BufferedImage image;private final VideoDecoder decoder=new VideoDecoder();public PreviewPanel(){setBackground(Color.BLACK);setPreferredSize(new Dimension(640,390));setMaximumSize(new Dimension(Integer.MAX_VALUE,Integer.MAX_VALUE));}public void setData(SgaFile f,List<Subtitle>s,SubtitleStyle st,int index){if(file!=f)decoder.clear();file=f;subtitles=s;style=st;frame=Math.max(0,Math.min(index,f==null?0:f.videoChunks().size()-1));refresh();}public void refresh(){image=null;if(file!=null&&!file.videoChunks().isEmpty())try{image=decoder.decode(file,frame);long ms=Math.round(frame*1000d/file.frameRate());var sub=subtitles.stream().filter(x->x.activeAt(ms)).findFirst().orElse(null);if(sub!=null)image=new SubtitleRenderer().render(image,sub.text(),style);}catch(Exception ignored){}repaint();}protected void paintComponent(Graphics g){super.paintComponent(g);if(image==null){g.setColor(new Color(110,130,160));g.setFont(getFont().deriveFont(Font.BOLD,16));String t=file==null?"Ouvrez un fichier SGA":"Aperçu indisponible pour ce profil";g.drawString(t,(getWidth()-g.getFontMetrics().stringWidth(t))/2,getHeight()/2);return;}double scale=Math.min((getWidth()-20d)/image.getWidth(),(getHeight()-20d)/image.getHeight());int w=(int)(image.getWidth()*scale),h=(int)(image.getHeight()*scale);g.drawImage(image,(getWidth()-w)/2,(getHeight()-h)/2,w,h,null);}}
